Method.Source:
/// <summary>
/// The extension is added to enable/disable the fields "Check proforma" and "Check proforma grace days" on the form "Credit management parameters"
/// based on the value of "Document status for credit check" field.
/// If the value of "Document status for credit check" field is "METCreditCheck" (Optimisation) ,
/// then the above mentioned two fields will be disabled, otherwise they will be enabled.
/// </summary>   
public int active()
{
    boolean isEnabled = true;

    CredManTmpStatusCheckSetup tmpStatusCheckSetup = this.cursor();

    this.formRun().lock();

    if(tmpStatusCheckSetup.DocumentStatus == CredManDocumentStatusCheck::METCreditCheck)
    {
        isEnabled = false;
    }

    this.object(fieldNum(CredManTmpStatusCheckSetup, CheckProforma)).enabled(isEnabled);
    this.object(fieldNum(CredManTmpStatusCheckSetup,CheckProformaGraceDays)).enabled(isEnabled);

    this.formRun().unlock();

    return next active();
}
